package com.JDBC.prac.Banking;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.UUID;@Servicepublic class CustomerService {    private final CustomerRepository customerRepository;    private final TransactionRepository transactionRepository;    public CustomerService(            CustomerRepository customerRepository,            TransactionRepository transactionRepository) {        this.customerRepository = customerRepository;        this.transactionRepository = transactionRepository;    }    @Transactional    public Customer registerCustomer(Customer customer) {        String accountNumber = "1000"                + UUID.randomUUID()                .toString()                .replace("-", "")                .substring(0, 10);        customer.setAccountNumber(accountNumber);        customer.setBalance(BigDecimal.ZERO);        return customerRepository.save(customer);    }    @Transactional    public Customer deposit(int customerID, BigDecimal amount) {        validateAmount(amount);        Customer customer = getCustomer(customerID);        BigDecimal newBalance = customer.getBalance().add(amount);        customer.setBalance(newBalance);        customerRepository.save(customer);        Transaction transaction = new Transaction(                customerID, "DEPOSIT", amount);        transactionRepository.save(transaction);        return customer;    }    @Transactional    public Customer withdraw(int customerID, BigDecimal amount) {        validateAmount(amount);        Customer customer = getCustomer(customerID);        BigDecimal currentBalance = customer.getBalance();        if (currentBalance.compareTo(amount) < 0) {            throw new IllegalArgumentException(                    "Insufficient balance!");        }        customer.setBalance(currentBalance.subtract(amount));        customerRepository.save(customer);        Transaction transaction = new Transaction(                customerID, "WITHDRAWAL", amount);        transactionRepository.save(transaction);        return customer;    }    public Customer getCustomer(int customerID) {        return customerRepository.findById(customerID)                .orElseThrow(() -> new IllegalArgumentException(                        "Customer account not found!"));    }    private void validateAmount(BigDecimal amount) {        if (amount == null                || amount.compareTo(BigDecimal.ZERO) <= 0                || amount.scale() > 2) {            throw new IllegalArgumentException(                    "Enter a valid amount greater than zero "                            + "with no more than two decimal places.");        }    }}